<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?= htmlspecialchars($url('/public/css/app.css'), ENT_QUOTES, 'UTF-8') ?>"><title>Ma proposition · <?= htmlspecialchars($application['name']) ?></title><body class="outdoor-mode"><?php require __DIR__ . '/../partials/header.php'; ?><main class="auth-page account-page"><?php $properties = $feature['properties'] ?? []; $coordinates = $feature['geometry']['coordinates'] ?? [null, null]; ?><h1>Ma proposition</h1><?php if ($notice): ?><p class="form-message success"><?= htmlspecialchars($notice) ?></p><?php endif; ?><section class="proposal-admin-card"><p><strong>Référence :</strong> <?= htmlspecialchars((string) ($properties['id'] ?? '')) ?></p><p><strong>Statut :</strong> <?= htmlspecialchars((string) ($properties['status'] ?? 'a_valider')) ?></p><p><strong>Adresse :</strong> <?= htmlspecialchars((string) ($properties['address'] ?? 'Non renseignée')) ?></p><p><strong>Coordonnées GPS :</strong> <?= htmlspecialchars((string) ($coordinates[1] ?? '')) ?>, <?= htmlspecialchars((string) ($coordinates[0] ?? '')) ?></p></section><?php if ($editable): ?><form class="proposal-admin-card" method="post" action="<?= htmlspecialchars($routeUrl('/ma-proposition/modifier'), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="source" value="<?= htmlspecialchars($source) ?>"><input type="hidden" name="id" value="<?= htmlspecialchars((string) ($properties['id'] ?? '')) ?>"><label>Essence<select name="species"><?php foreach ($planting['allowed_species'] as $species): ?><option value="<?= htmlspecialchars($species) ?>" <?= ($properties['species'] ?? '') === $species ? 'selected' : '' ?>><?= htmlspecialchars($species) ?></option><?php endforeach; ?></select></label><?php if ($source === 'donations'): ?><label>Conditionnement<select name="conditioning"><?php foreach ($planting['tree_conditioning'] as $key => $item): ?><option value="<?= htmlspecialchars($key) ?>" <?= ($properties['conditioning'] ?? '') === $key ? 'selected' : '' ?>><?= htmlspecialchars($item['label']) ?></option><?php endforeach; ?></select></label><label>Taille<select name="tree_size"><?php foreach ($planting['tree_sizes'] as $key => $item): ?><option value="<?= htmlspecialchars($key) ?>" <?= ($properties['tree_size'] ?? '') === $key ? 'selected' : '' ?>><?= htmlspecialchars($item['label']) ?></option><?php endforeach; ?></select></label><?php else: ?><fieldset><legend>Objectifs <small>3 maximum</small></legend><div class="objective-grid"><?php foreach ($planting['objectives'] as $key => $item): ?><label class="objective"><input type="checkbox" name="objectives[]" value="<?= htmlspecialchars($key) ?>" <?= in_array($key, (array) ($properties['objectives'] ?? []), true) ? 'checked' : '' ?>><span class="objective-tile"><span class="objective-icon"><?= htmlspecialchars($item['icon']) ?></span><span><?= htmlspecialchars($item['label']) ?></span></span></label><?php endforeach; ?></div></fieldset><?php endif; ?><label>Commentaire<textarea name="comment" rows="5" maxlength="1000"><?= htmlspecialchars((string) ($properties['comment'] ?? '')) ?></textarea></label><button>Enregistrer les modifications</button></form><?php else: ?><p>Cette proposition a été traitée et ne peut plus être modifiée.</p><?php endif; ?></main><?php require __DIR__ . '/../partials/footer.php'; ?></body></html>
